import * as fs from "node:fs";
import * as path from "node:path";
import { publicPair } from "./publicgames";

/**
 * Community matchup records — what two agents did against each other, never a
 * ranking. A leaderboard needs far more data density than this lane has, and a
 * head-to-head record is the one shape that stays true at n=4
 * (docs/plans/2026-07-25-community-lane-v2.md).
 *
 * Generated by CI after merge, not by submitters. The bytes are a public data
 * contract (the product page fetches the JSON directly), so the ordering below
 * is a total order at BOTH levels and is independent of the order runDirs
 * happen to arrive in.
 */

export const MATCHUPS_SCHEMA = "laplace-bench-standings-v2";

export interface MatchupBreakdown {
  /** Raw specs, oriented to the headline pair — not to their own sort order. */
  left_agent: string;
  right_agent: string;
  games: number;
  left_wins: number;
  right_wins: number;
  draws: number;
  /** How the games ended. Properties of the game, not of either side. */
  center_wins: number;
  elim_wins: number;
  horizon_draws: number;
  repetition_draws: number;
  /** Errors per turn rounded to 3 decimals; null when that side had no turns. */
  left_err_per_turn: number | null;
  right_err_per_turn: number | null;
}

export interface Matchup {
  headline: { left: string; right: string };
  games: number;
  left_wins: number;
  right_wins: number;
  draws: number;
  /** ISO start time of the most recent run in this matchup; "" if unrecorded. */
  last_played: string;
  /** Reference to the highest-sorting game, for pointing at a specific log. */
  last_game: string;
  breakdown: MatchupBreakdown[];
}

export interface MatchupAgent {
  agent: string;
  games: number;
  err_per_turn: number | null;
}

export interface MatchupData {
  schema: typeof MATCHUPS_SCHEMA;
  lane: "community";
  game_count: number;
  run_count: number;
  matchup_count: number;
  matchups: Matchup[];
  /** Participants, by name. Carries no wins — this is not a ranking. */
  agents: MatchupAgent[];
}

/** Ordinal code-unit comparison — environment-independent, no locale collation. */
const ord = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

/**
 * `run.json`'s recorded start time. Absent or malformed reads as "" so an old
 * or hand-assembled run sorts last instead of failing the whole publish.
 */
function readStartedAt(runDir: string): string {
  try {
    const raw = fs.readFileSync(path.join(runDir, "run.json"), "utf8");
    const started = JSON.parse(raw).started_at;
    return typeof started === "string" ? started : "";
  } catch {
    return "";
  }
}

const round3 = (errors: number, turns: number): number | null =>
  turns > 0 ? Math.round((errors / turns) * 1000) / 1000 : null;

interface SideAcc {
  wins: number;
  errors: number;
  turns: number;
}

interface BreakdownAcc {
  leftAgent: string;
  rightAgent: string;
  games: number;
  draws: number;
  centerWins: number;
  elimWins: number;
  horizonDraws: number;
  repetitionDraws: number;
  lastPlayed: string;
  lastGame: string;
  left: SideAcc;
  right: SideAcc;
}

interface MatchupAcc {
  left: string;
  right: string;
  games: number;
  leftWins: number;
  rightWins: number;
  draws: number;
  lastPlayed: string;
  lastGame: string;
  breakdowns: Map<string, BreakdownAcc>;
}

interface AgentAcc {
  agent: string;
  games: number;
  errors: number;
  turns: number;
}

const newSide = (): SideAcc => ({ wins: 0, errors: 0, turns: 0 });

/**
 * Single computation behind both the Markdown table and the public JSON.
 *
 * Orientation is owned by the HEADLINE pair, not by the raw specs: canonicalize
 * the two headline keys, then map every game's A/B onto that orientation.
 * Sorting raw specs first would let two breakdowns under one headline disagree
 * about which side is "left", making left_wins/right_wins unsummable.
 */
export function matchupData(runDirs: string[]): MatchupData {
  const matchups = new Map<string, MatchupAcc>();
  const agents = new Map<string, AgentAcc>();
  let gameCount = 0;
  let runCount = 0;

  for (const runDir of runDirs) {
    const gamesDir = path.join(runDir, "games");
    if (!fs.existsSync(gamesDir)) continue;
    runCount++;
    const runId = path.basename(path.resolve(runDir));
    // Recency has to come from the data. The run reference starts with the
    // submitter's login in the public ledger, so ordering by it would sort by
    // account name and call it "most recent".
    const startedAt = readStartedAt(runDir);

    for (const gameId of fs.readdirSync(gamesDir).sort()) {
      const finalPath = path.join(gamesDir, gameId, "final.json");
      if (!fs.existsSync(finalPath)) continue;
      const fin = JSON.parse(fs.readFileSync(finalPath, "utf8"));
      gameCount++;

      const specA: string = fin.teams.A.agent;
      const specB: string = fin.teams.B.agent;

      // Participants are recorded for every counted game, including games that
      // never reach the public matchup list.
      for (const t of [fin.teams.A, fin.teams.B] as const) {
        let a = agents.get(t.agent);
        if (!a) {
          a = { agent: t.agent, games: 0, errors: 0, turns: 0 };
          agents.set(t.agent, a);
        }
        a.games++;
        a.errors += t.legalityFailures + t.formatFailures;
        a.turns += t.turns;
      }

      const pair = publicPair(specA, specB);
      if (!pair) continue;

      const left = pair.leftId;
      const right = pair.rightId;
      const leftTeam = pair.leftSide;
      const rightTeam = pair.leftSide === "A" ? "B" : "A";
      const leftSpec = pair.leftAgent;
      const rightSpec = pair.rightAgent;

      const mKey = `${left}\u0000${right}`;
      let m = matchups.get(mKey);
      if (!m) {
        m = {
          left,
          right,
          games: 0,
          leftWins: 0,
          rightWins: 0,
          draws: 0,
          lastPlayed: "",
          lastGame: "",
          breakdowns: new Map(),
        };
        matchups.set(mKey, m);
      }

      const bKey = `${leftSpec}\u0000${rightSpec}`;
      let b = m.breakdowns.get(bKey);
      if (!b) {
        b = {
          leftAgent: leftSpec,
          rightAgent: rightSpec,
          games: 0,
          draws: 0,
          centerWins: 0,
          elimWins: 0,
          horizonDraws: 0,
          repetitionDraws: 0,
          lastPlayed: "",
          lastGame: "",
          left: newSide(),
          right: newSide(),
        };
        m.breakdowns.set(bKey, b);
      }

      const gameRef = `${runId}/${gameId}`;
      if (ord(gameRef, m.lastGame) > 0) m.lastGame = gameRef;
      if (ord(gameRef, b.lastGame) > 0) b.lastGame = gameRef;
      if (ord(startedAt, m.lastPlayed) > 0) m.lastPlayed = startedAt;
      if (ord(startedAt, b.lastPlayed) > 0) b.lastPlayed = startedAt;

      m.games++;
      b.games++;

      if (fin.winner === null) {
        m.draws++;
        b.draws++;
        if (fin.reason === "horizon_draw") b.horizonDraws++;
        if (fin.reason === "repetition_draw") b.repetitionDraws++;
      } else if (fin.winner === leftTeam) {
        m.leftWins++;
        b.left.wins++;
        if (fin.reason === "center") b.centerWins++;
        if (fin.reason === "elimination") b.elimWins++;
      } else {
        m.rightWins++;
        b.right.wins++;
        if (fin.reason === "center") b.centerWins++;
        if (fin.reason === "elimination") b.elimWins++;
      }

      for (const [side, team] of [
        [b.left, leftTeam],
        [b.right, rightTeam],
      ] as const) {
        const t = fin.teams[team];
        side.errors += t.legalityFailures + t.formatFailures;
        side.turns += t.turns;
      }
    }
  }

  const sortedMatchups = [...matchups.values()]
    .sort(
      (a, b) =>
        b.games - a.games ||
        ord(b.lastPlayed, a.lastPlayed) ||
        ord(b.lastGame, a.lastGame) ||
        ord(a.left, b.left) ||
        ord(a.right, b.right)
    )
    .map((m) => ({
      headline: { left: m.left, right: m.right },
      games: m.games,
      left_wins: m.leftWins,
      right_wins: m.rightWins,
      draws: m.draws,
      last_played: m.lastPlayed,
      last_game: m.lastGame,
      // Breakdowns share a headline key, so raw specs are the only thing left
      // to break a tie with — without them this is not a total order.
      breakdown: [...m.breakdowns.values()]
        .sort(
          (a, b) =>
            b.games - a.games ||
            ord(b.lastPlayed, a.lastPlayed) ||
            ord(b.lastGame, a.lastGame) ||
            ord(a.leftAgent, b.leftAgent) ||
            ord(a.rightAgent, b.rightAgent)
        )
        .map((b) => ({
          left_agent: b.leftAgent,
          right_agent: b.rightAgent,
          games: b.games,
          left_wins: b.left.wins,
          right_wins: b.right.wins,
          draws: b.draws,
          center_wins: b.centerWins,
          elim_wins: b.elimWins,
          horizon_draws: b.horizonDraws,
          repetition_draws: b.repetitionDraws,
          left_err_per_turn: round3(b.left.errors, b.left.turns),
          right_err_per_turn: round3(b.right.errors, b.right.turns),
        })),
    }));

  return {
    schema: MATCHUPS_SCHEMA,
    lane: "community",
    game_count: gameCount,
    run_count: runCount,
    matchup_count: sortedMatchups.length,
    matchups: sortedMatchups,
    agents: [...agents.values()]
      .sort((a, b) => ord(a.agent, b.agent))
      .map((a) => ({
        agent: a.agent,
        games: a.games,
        err_per_turn: round3(a.errors, a.turns),
      })),
  };
}

/** Public JSON artifact: 2-space indent, exactly one trailing newline. */
export function matchupsJson(runDirs: string[]): string {
  return JSON.stringify(matchupData(runDirs), null, 2) + "\n";
}

const pct = (n: number | null): string => (n === null ? "-" : n.toFixed(3));

/**
 * Human-readable rendering of the same data. Generated by CI — the header says
 * so, because a hand-edited copy would silently disagree with the JSON the
 * product page actually reads.
 */
export function matchupsMarkdown(runDirs: string[]): string {
  const data = matchupData(runDirs);
  const lines = [
    `# Community matchups`,
    ``,
    `${data.game_count} games across ${data.run_count} run(s), ` +
      `${data.matchup_count} matchup(s). Most-played first.`,
    ``,
    `Generated by CI from \`community/runs\` — do not edit by hand.`,
    ``,
  ];

  if (data.matchups.length === 0) {
    lines.push(`_No public matchups yet._`, ``);
  }

  for (const m of data.matchups) {
    lines.push(
      `## ${m.headline.left} vs ${m.headline.right}`,
      ``,
      `${m.games} game(s) — ${m.left_wins}W-${m.draws}D-${m.right_wins}L ` +
        `from \`${m.headline.left}\`'s side.`,
      ``,
      `| ${m.headline.left} | ${m.headline.right} | G | W | D | L | center | elim | D:horizon | D:repetition | err/turn L | err/turn R |`,
      `|---|---|---|---|---|---|---|---|---|---|---|---|`,
      ...m.breakdown.map(
        (b) =>
          `| \`${b.left_agent}\` | \`${b.right_agent}\` | ${b.games} | ${b.left_wins} | ${b.draws} | ${b.right_wins} | ${b.center_wins} | ${b.elim_wins} | ${b.horizon_draws} | ${b.repetition_draws} | ${pct(b.left_err_per_turn)} | ${pct(b.right_err_per_turn)} |`
      ),
      ``
    );
  }

  lines.push(
    `## Participants`,
    ``,
    `| agent | games | err/turn |`,
    `|---|---|---|`,
    ...data.agents.map(
      (a) => `| \`${a.agent}\` | ${a.games} | ${pct(a.err_per_turn)} |`
    ),
    ``,
    `Agent labels are self-reported; replay verification proves the games are ` +
      `legal and correctly scored, not who produced the moves.`
  );
  return lines.join("\n") + "\n";
}
